import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.joining;class Result {public static List<Integer> absolutePermutation(int n, int k) {if (k == 0) {List<Integer> res = new ArrayList<>(n);for (int i = 1; i <= n; i++) res.add(i);return res;}if (n % (2 * k) != 0) {return Collections.singletonList(-1);}List<Integer> res = new ArrayList<>(n);for (int i = 0; i < n / (2 * k); i++) {for (int j = 1; j <= k; j++) {res.add(i * 2 * k + j + k);}for (int j = 1; j <= k; j++) {res.add(i * 2 * k + j);}}return res;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String line = bufferedReader.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());IntStream.range(0, t).forEach(tItr -> {try {String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int n = Integer.parseInt(firstMultipleInput[0]);int k = Integer.parseInt(firstMultipleInput[1]);List<Integer> result = Result.absolutePermutation(n, k);bufferedWriter.write(result.stream().map(Object::toString).collect(joining(" ")) + "\n");} catch (IOException ex) {throw new RuntimeException(ex);}});bufferedReader.close();bufferedWriter.close();}}